package com.cni.ingestion; import com.cni.casefile.InvestigationCase; import com.cni.user.AppUser; import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="data_ingestions") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class DataIngestion{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="case_id",nullable=false)private InvestigationCase investigationCase;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="created_by",nullable=false)private AppUser createdBy;@Column(nullable=false)private String sourceType;@Column(nullable=false)private String fileName;private long recordCount;private String status;@Column(columnDefinition="TEXT")private String notes;private String storedName;private String sha256;private String contentType;private long sizeBytes;@Column(name="created_at",nullable=false)private Instant createdAt;}
